//! Go standard-library behaviour that block D00.2 depends on and that Rust's std does not
//! reproduce exactly (ON-DEMAND tool code, Go 1.25.12).
//!
//! go-file: $GOROOT/src/unicode/letter.go
//! go-file: $GOROOT/src/unicode/digit.go
//!
//! `unicode_tables.rs` holds Go's category tables (generated by tracker `govec/cmd/rsgen`).

pub mod unicode_tables;

/// `unicode.Range16`.
pub struct Range16 {
    pub lo: u16,
    pub hi: u16,
    pub stride: u16,
}

/// `unicode.Range32`.
pub struct Range32 {
    pub lo: u32,
    pub hi: u32,
    pub stride: u32,
}

/// `unicode.RangeTable`.
pub struct RangeTable {
    pub r16: &'static [Range16],
    pub r32: &'static [Range32],
    pub latin_offset: usize,
}

/// `unicode.MaxLatin1`.
const MAX_LATIN1: u32 = 0xff;

// go-std: unicode.is16 L1
fn is16(ranges: &[Range16], r: u16) -> bool {
    if ranges.len() <= 18 || r <= MAX_LATIN1 as u16 {
        for range in ranges {
            if r < range.lo {
                return false;
            }
            if r <= range.hi {
                return range.stride == 1 || (r - range.lo).is_multiple_of(range.stride);
            }
        }
        return false;
    }
    // binary search over ranges
    let (mut lo, mut hi) = (0usize, ranges.len());
    while lo < hi {
        let m = lo + (hi - lo) / 2;
        let range = &ranges[m];
        if range.lo <= r && r <= range.hi {
            return range.stride == 1 || (r - range.lo).is_multiple_of(range.stride);
        }
        if r < range.lo {
            hi = m;
        } else {
            lo = m + 1;
        }
    }
    false
}

// go-std: unicode.is32 L1
fn is32(ranges: &[Range32], r: u32) -> bool {
    if ranges.len() <= 18 {
        for range in ranges {
            if r < range.lo {
                return false;
            }
            if r <= range.hi {
                return range.stride == 1 || (r - range.lo).is_multiple_of(range.stride);
            }
        }
        return false;
    }
    // binary search over ranges
    let (mut lo, mut hi) = (0usize, ranges.len());
    while lo < hi {
        let m = lo + (hi - lo) / 2;
        let range = &ranges[m];
        if range.lo <= r && r <= range.hi {
            return range.stride == 1 || (r - range.lo).is_multiple_of(range.stride);
        }
        if r < range.lo {
            hi = m;
        } else {
            lo = m + 1;
        }
    }
    false
}

/// `unicode.Is` reports whether the rune is in the specified table of ranges.
// go-std: unicode.Is L1
pub fn is(range_tab: &RangeTable, r: char) -> bool {
    let r = r as u32;
    let r16 = range_tab.r16;
    // Compare as uint32 to correctly handle negative runes.
    if !r16.is_empty() && r <= u32::from(r16[r16.len() - 1].hi) {
        return is16(r16, r as u16);
    }
    let r32 = range_tab.r32;
    if !r32.is_empty() && r >= r32[0].lo {
        return is32(r32, r);
    }
    false
}

/// `unicode.IsOneOf` reports whether the rune is a member of one of the ranges.
// go-std: unicode.IsOneOf L1
pub fn is_one_of(ranges: &[&RangeTable], r: char) -> bool {
    ranges.iter().any(|inside| is(inside, r))
}

/// `unicode.IsDigit` reports whether the rune is a decimal digit.
// go-std: unicode.IsDigit L1
pub fn is_digit(r: char) -> bool {
    if (r as u32) <= MAX_LATIN1 {
        return r.is_ascii_digit();
    }
    is(&unicode_tables::Nd, r)
}

/// `unicode.IsDigit(rune(b))` for a byte of a Go string (`rune(precision[0])`).
// glue: Go rune(byte) conversion
pub fn is_digit_byte(b: u8) -> bool {
    is_digit(char::from(b))
}

/// `strings.ToUpper` for a valid UTF-8 string: `unicode.ToUpper` on every rune (Go's
/// simple case mapping, which never expands a rune).
// go-std: strings.ToUpper L1
pub fn to_upper(s: &str) -> String {
    s.chars().map(to_upper_rune).collect()
}

pub(crate) mod ftoaryu;
mod powers;

/// `utf8.DecodeRune`: the rune at the start of `s` and its width; `(RuneError, 1)` for an
/// invalid or incomplete encoding, `(RuneError, 0)` for empty input.
// go-std: unicode/utf8.DecodeRune L2 (validity by std::str::from_utf8)
pub fn decode_rune(s: &[u8]) -> (char, usize) {
    if s.is_empty() {
        return ('\u{fffd}', 0);
    }
    let want = match s[0] {
        0x00..=0x7f => return (char::from(s[0]), 1),
        0xc2..=0xdf => 2,
        0xe0..=0xef => 3,
        0xf0..=0xf4 => 4,
        _ => return ('\u{fffd}', 1),
    };
    if s.len() >= want
        && let Ok(t) = std::str::from_utf8(&s[..want])
        && let Some(c) = t.chars().next()
    {
        return (c, want);
    }
    ('\u{fffd}', 1)
}

/// `utf8.RuneCount`: invalid bytes count one each.
// go-std: unicode/utf8.RuneCount L2 (via decode_rune)
pub fn rune_count(mut s: &[u8]) -> usize {
    let mut n = 0;
    while !s.is_empty() {
        s = &s[decode_rune(s).1..];
        n += 1;
    }
    n
}

/// `for _, r := range s` over a Go string: an invalid byte yields U+FFFD.
// glue: Go range over a string
pub fn runes(mut s: &[u8]) -> impl Iterator<Item = char> + '_ {
    std::iter::from_fn(move || {
        if s.is_empty() {
            return None;
        }
        let (r, w) = decode_rune(s);
        s = &s[w..];
        Some(r)
    })
}

/// `strconv.IsPrint`: Go's printable runes (letters, marks, numbers, punctuation, symbols
/// and U+0020), from the generated table `IS_PRINT`.
// go-std: strconv.IsPrint L2 (table generated from Go's IsPrint)
pub fn is_print(r: char) -> bool {
    let r = r as u32;
    let t = unicode_tables::IS_PRINT;
    t.binary_search_by(|(lo, hi)| {
        if *hi < r {
            std::cmp::Ordering::Less
        } else if *lo > r {
            std::cmp::Ordering::Greater
        } else {
            std::cmp::Ordering::Equal
        }
    })
    .is_ok()
}

/// `unicode.IsLetter` reports whether the rune is a letter (category L).
// go-std: unicode.IsLetter L1
pub fn is_letter(r: char) -> bool {
    use unicode_tables::{Ll, Lm, Lo, Lt, Lu};
    is_one_of(&[&Lu, &Ll, &Lt, &Lm, &Lo], r)
}

/// `strings.ToLower` for a valid UTF-8 string: `unicode.ToLower` on every rune.
// go-std: strings.ToLower L1
pub fn to_lower(s: &str) -> String {
    s.chars().map(to_lower_rune).collect()
}

/// `unicode.UpperCase`, `LowerCase`, `TitleCase`: indices into the deltas of a case range.
const UPPER_CASE: usize = 0;
const LOWER_CASE: usize = 1;
/// `unicode.MaxRune`: a delta above it is `unicode.UpperLower` (runes alternate upper and
/// lower case).
const MAX_RUNE: i32 = 0x10FFFF;

/// `unicode.to`: maps the rune using the specified case mapping (`unicode.CaseRanges`).
// go-std: unicode.to L1
fn to_case(case: usize, r: char) -> char {
    let ranges = unicode_tables::CASE_RANGES;
    let r32 = r as u32;
    // binary search over ranges
    let (mut lo, mut hi) = (0, ranges.len());
    while lo < hi {
        let m = lo + (hi - lo) / 2;
        let (clo, chi, delta) = ranges[m];
        if clo <= r32 && r32 <= chi {
            let d = delta[case];
            if d > MAX_RUNE {
                // In an Upper-Lower sequence, which always starts with an UpperCase letter,
                // the real deltas always look like: {0, 1, 0} (UpperCase (Lower is next)),
                // {-1, 0, -1} (LowerCase (Upper, Title are previous)). The characters at
                // even offsets from the beginning of the sequence are upper case; the ones
                // at odd offsets are lower. The correct mapping can be done by clearing or
                // setting the low bit in the sequence offset. The constants UpperCase and
                // TitleCase are even while LowerCase is odd so we take the low bit from case.
                return char::from_u32(clo + (((r32 - clo) & !1) | (case as u32 & 1))).unwrap_or(r);
            }
            return char::from_u32((r32 as i64 + i64::from(d)) as u32).unwrap_or(r);
        }
        if r32 < clo {
            hi = m;
        } else {
            lo = m + 1;
        }
    }
    r
}

/// `unicode.ToUpper` maps the rune to upper case.
// go-std: unicode.ToUpper L1
pub fn to_upper_rune(r: char) -> char {
    if r.is_ascii() {
        return r.to_ascii_uppercase();
    }
    to_case(UPPER_CASE, r)
}

/// `unicode.ToLower` maps the rune to lower case.
// go-std: unicode.ToLower L1
pub fn to_lower_rune(r: char) -> char {
    if r.is_ascii() {
        return r.to_ascii_lowercase();
    }
    to_case(LOWER_CASE, r)
}

/// `unicode.SimpleFold` iterates over Unicode code points equivalent under the
/// Unicode-defined simple case folding: the smallest rune > r if one exists, or else the
/// smallest rune >= 0. (`asciiFold` and `caseOrbit` are the generated `FOLD_ORBIT`.)
// go-std: unicode.SimpleFold L1
pub fn simple_fold(r: char) -> char {
    let orbit = unicode_tables::FOLD_ORBIT;
    if let Ok(i) = orbit.binary_search_by_key(&(r as u32), |&(from, _)| from) {
        return char::from_u32(orbit[i].1).unwrap_or(r);
    }
    // No folding specified. This is a one- or two-element equivalence class containing
    // rune and ToLower(rune) and ToUpper(rune) if they are different from rune.
    let l = to_lower_rune(r);
    if l != r {
        return l;
    }
    to_upper_rune(r)
}

/// `strings.EqualFold` reports whether s and t, interpreted as UTF-8 strings, are equal
/// under simple Unicode case-folding, which is a more general form of case-insensitivity.
// go-std: strings.EqualFold L1 (valid UTF-8 input)
pub fn equal_fold(s: &str, t: &str) -> bool {
    let mut tc = t.chars();
    for mut sr in s.chars() {
        let Some(mut tr) = tc.next() else {
            return false;
        };
        // If they match, keep going; if not, return false.
        // Easy case.
        if tr == sr {
            continue;
        }
        // Make sr < tr to simplify what follows.
        if tr < sr {
            std::mem::swap(&mut tr, &mut sr);
        }
        // Fast check for ASCII.
        if tr.is_ascii() {
            // ASCII only, sr/tr must be upper/lower case
            if sr.is_ascii_uppercase() && tr as u32 == sr as u32 + 32 {
                continue;
            }
            return false;
        }
        // General case. SimpleFold(x) returns the next equivalent rune > x or wraps around
        // to smaller values.
        let mut r = simple_fold(sr);
        while r != sr && r < tr {
            r = simple_fold(r);
        }
        if r == tr {
            continue;
        }
        return false;
    }
    // One string is empty. Are both?
    tc.next().is_none()
}

